export interface Reading{channel:string;unit:string;value:number;at:number}
interface ParsedReading{channel:string;millivolts:number;at:number}
interface ChannelSummary{count:number;min:number;max:number;worst:string}
export interface BatchResult{ok:boolean;error?:string;readings?:number;labels?:string[];channels?:Record<string,ChannelSummary>;alerts?:string[];report?:string}
const MAX_READINGS=500;const UNITS=["uV","mV","V"];
export function processBatch(raw){const be=validateBatch(raw);if(be!==null)return{ok:false,error:be};const entries=raw.readings;const parsed=[];for(let i=0;i<entries.length;i++){const o=parseReading(entries[i],i);if(typeof o==="string")return{ok:false,error:o};parsed.push({channel:o.channel,millivolts:normalizeValue(o.unit,o.value),at:o.at});}const labels=parsed.map(r=>classifySignal(r.millivolts));const alerts=collectAlerts(parsed);const channels=channelSummaries(parsed,labels);const report=buildReport(parsed.length,Object.keys(channels).length,alerts.length,labels);return{ok:true,readings:parsed.length,labels,channels,alerts,report};}
function validateBatch(raw){if(typeof raw!=="object"||raw===null)return"malformed batch";const b=raw;if(!Array.isArray(b.readings))return"missing readings";if(b.readings.length===0)return"empty batch";if(b.readings.length>MAX_READINGS)return"batch too large";return null;}
function parseReading(entry,index){if(typeof entry!=="object"||entry===null)return"reading "+index+": malformed";const r=entry;if(typeof r.channel!=="string"||r.channel.length===0)return"reading "+index+": bad channel";if(UNITS.indexOf(r.unit)<0)return"reading "+index+": bad unit";if(!Number.isInteger(r.value))return"reading "+index+": bad value";if(!isNonNegativeInt(r.at))return"reading "+index+": bad timestamp";return{channel:r.channel,unit:r.unit,value:r.value,at:r.at};}
function isNonNegativeInt(v){return Number.isInteger(v)&&v>=0;}
function normalizeValue(unit,value){if(unit==="V")return value*1000;if(unit==="uV")return Math.trunc(value/1000);return value;}
export function classifySignal(m){if(m>=0&&m<50)return"standby";if(m>=50&&m<200)return"idle";if(m>=200&&m<600)return"active";if(m>=600&&m<900)return"loaded";if(m>=900)return"critical";return"negative";}
function severityRank(l){if(l==="negative")return 5;if(l==="critical")return 4;if(l==="loaded")return 3;if(l==="active")return 2;if(l==="idle")return 1;return 0;}
function collectAlerts(parsed){const a=[];for(const r of parsed){if(r.millivolts>=900)a.push(r.channel+":critical");else if(r.millivolts<0)a.push(r.channel+":negative");else if(r.millivolts>=600&&r.millivolts<900)a.push(r.channel+":loaded");}return a;}
function channelSummaries(parsed,labels){const c={};for(let i=0;i<parsed.length;i++){const r=parsed[i];const e=c[r.channel];if(e===undefined){c[r.channel]={count:1,min:r.millivolts,max:r.millivolts,worst:labels[i]};continue;}e.count++;if(r.millivolts<e.min)e.min=r.millivolts;if(r.millivolts>e.max)e.max=r.millivolts;if(severityRank(labels[i])>severityRank(e.worst))e.worst=labels[i];}return c;}
function buildReport(n,cn,an,labels){let w="standby";for(const l of labels){if(severityRank(l)>severityRank(w))w=l;}return"readings="+n+";channels="+cn+";alerts="+an+";worst="+w;}
EOF
