  else {raw={readings:Array(3).fill().map(()=>makeReading())}; if(rnd(3)===0)raw.readings[1]={channel:"chX",unit:"bogus",value:5,at:0}; if(rnd(3)===0)raw.readings[rnd(3)]=null;}
